final class SimulationLabPage extends StatefulWidget { const SimulationLabPage({super.key}); @override State<SimulationLabPage> createState()=>_SimulationLabPageState(); }
final class _SimulationLabPageState extends State<SimulationLabPage> {
  String filter='All';
  @override Widget build(BuildContext context){
    final categories=['All',...{for(final s in simulationScenarios)s.category}];
    final visible=filter=='All'?simulationScenarios:simulationScenarios.where((s)=>s.category==filter).toList();
    return Scaffold(appBar:AppBar(title:const Text('Real-world simulation lab'),actions:[TextButton.icon(onPressed:()=>context.go('/home'),icon:const Icon(Icons.home),label:const Text('Today')),const SizedBox(width:12)]),body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1120),child:ListView(padding:const EdgeInsets.all(32),children:[
      Text('Practice English under realistic pressure',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:8),const Text('General English, workplace communication, procurement, manufacturing, meetings, calls, email, presentations, and travel. Each simulation includes roles, context, objectives, changing pressure, and structured feedback.'),const SizedBox(height:20),
      Wrap(spacing:8,runSpacing:8,children:[for(final c in categories)ChoiceChip(label:Text(c),selected:filter==c,onSelected:(_)=>setState(()=>filter=c))]),const SizedBox(height:24),
      GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:355,mainAxisExtent:260,crossAxisSpacing:16,mainAxisSpacing:16),itemCount:visible.length,itemBuilder:(context,i){final s=visible[i];return Card(clipBehavior:Clip.antiAlias,child:InkWell(onTap:()=>context.go('/simulation/${s.id}'),child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[CircleAvatar(child:Icon(_icon(s.id))),const Spacer(),Chip(label:Text(s.level))]),const SizedBox(height:12),Text(s.title,style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:8),Text(s.context,maxLines:3,overflow:TextOverflow.ellipsis),const Spacer(),Row(children:[Icon(Icons.schedule,size:18),const SizedBox(width:6),Text('${s.minutes} min'),const Spacer(),Text(s.category,style:Theme.of(context).textTheme.labelMedium)]),const SizedBox(height:12),const Row(mainAxisAlignment:MainAxisAlignment.end,children:[Text('Open scenario'),SizedBox(width:6),Icon(Icons.arrow_forward)])]))));}),
    ]))))); }
  IconData _icon(String id)=>id.contains('factory')?Icons.factory:id.contains('email')?Icons.email:id.contains('teams')?Icons.groups:id.contains('travel')?Icons.flight:id.contains('phone')?Icons.call:id.contains('presentation')?Icons.present_to_all:Icons.record_voice_over;
}

final class SimulationRoomPage extends StatefulWidget { const SimulationRoomPage({required this.id,super.key}); final String id; @override State<SimulationRoomPage> createState()=>_SimulationRoomPageState(); }
final class _SimulationRoomPageState extends State<SimulationRoomPage>{
  final answer=TextEditingController(); final transcript=<String>[]; int turn=0; String? feedback;
  SimulationScenario get scenario=>simulationScenarios.firstWhere((s)=>s.id==widget.id,orElse:()=>simulationScenarios.first);
  @override void dispose(){answer.dispose();super.dispose();}
  @override Widget build(BuildContext context){final s=scenario;return Scaffold(appBar:AppBar(title:Text(s.title),actions:[TextButton.icon(onPressed:()=>context.go('/simulations'),icon:const Icon(Icons.grid_view),label:const Text('All simulations')),const SizedBox(width:12)]),body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1120),child:Row(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
    Expanded(flex:4,child:ListView(padding:const EdgeInsets.all(24),children:[Text('Briefing',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),_Info('Context',s.context),_Info('Your objective',s.objective),_Info('Pressure',s.pressure),_Info('Roles',s.roles.join('\n')),const SizedBox(height:12),Text('Useful language',style:Theme.of(context).textTheme.titleMedium),for(final p in s.keyPhrases)ListTile(dense:true,leading:const Icon(Icons.chat_bubble_outline),title:Text(p)),]),),
    const VerticalDivider(width:1),Expanded(flex:6,child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Live role-play',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:6),Text('Turn ${turn+1} • Respond naturally. The scenario develops from your answer.'),const SizedBox(height:16),Expanded(child:Card(color:Theme.of(context).colorScheme.surfaceContainerHighest,child:ListView(padding:const EdgeInsets.all(18),children:[_Bubble('Scenario partner',turn==0?s.opening:_promptFor(turn),false),for(int i=0;i<transcript.length;i++)_Bubble(i.isEven?'You':'Scenario partner',transcript[i],i.isEven)]))),const SizedBox(height:12),TextField(controller:answer,minLines:2,maxLines:5,decoration:const InputDecoration(labelText:'Your English response',hintText:'Write what you would say or send in this situation…')),const SizedBox(height:10),Row(children:[OutlinedButton.icon(onPressed:_hint,icon:const Icon(Icons.lightbulb_outline),label:const Text('Coaching hint')),const Spacer(),FilledButton.icon(onPressed:_submit,icon:const Icon(Icons.send),label:Text(turn>=3?'Finish and review':'Send response'))]),if(feedback!=null)Padding(padding:const EdgeInsets.only(top:12),child:Card(color:Theme.of(context).colorScheme.primaryContainer,child:Padding(padding:const EdgeInsets.all(16),child:Text(feedback!))))]))),
  ]))));}
  void _submit(){final text=answer.text.trim();if(text.isEmpty)return;setState((){transcript.add(text);answer.clear();final score=_score(text);transcript.add(_reply(text));turn++;feedback='Coach snapshot: $score/100 • ${_feedback(text)}';if(turn>=4)feedback='Simulation review: $score/100 • You completed ${turn} response turns. ${_feedback(text)} Repeat the scenario using one clarification question, one evidence-based statement, and one explicit next action.';});}
  int _score(String text){var score=45;final words=text.split(RegExp(r'\s+')).length;if(words>=12)score+=15;if(text.contains('?'))score+=10;if(RegExp(r'\b(please|could|would|confirm|because|therefore|next|deadline|evidence)\b',caseSensitive:false).hasMatch(text))score+=20;if(RegExp(r'\b(I think|maybe|thing|stuff)\b',caseSensitive:false).hasMatch(text))score-=5;return score.clamp(0,100);}
  String _feedback(String text){final parts=<String>[];if(!text.contains('?'))parts.add('Add a focused clarification question.');if(text.split(RegExp(r'\s+')).length<12)parts.add('Develop the answer with context and a clear action.');if(!RegExp(r'\b(confirm|agree|send|review|deadline|next)\b',caseSensitive:false).hasMatch(text))parts.add('Close with an owner, action, or deadline.');return parts.isEmpty?'Clear, purposeful language. Now improve precision by paraphrasing the partner’s key point.':parts.join(' ');}
  String _reply(String _){const replies=['I understand your point, but what specific evidence or commitment do you need from us?','That may be possible. We need to consider cost, timing, and operational risk. Which point should we resolve first?','I can offer a partial solution, although the deadline remains difficult. How would you like to document the next step?','Before we close, please summarize the agreement, owner, and due date.'];return replies[turn < replies.length ? turn : replies.length - 1];}
  String _promptFor(int t)=>const ['Please clarify your priority and the evidence you need.','A new constraint has appeared. The original deadline may not be possible.','One participant disagrees and asks for a lower-cost alternative.','Close the interaction with a precise summary and next actions.'][t < 4 ? t : 3];
  void _hint(){setState(()=>feedback='Hint: ${scenario.keyPhrases[turn%scenario.keyPhrases.length]}');}
}
final class _Info extends StatelessWidget{const _Info(this.title,this.text);final String title,text;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.titleSmall),const SizedBox(height:4),Text(text)]));}
final class _Bubble extends StatelessWidget{const _Bubble(this.label,this.text,this.mine);final String label,text;final bool mine;@override Widget build(BuildContext context)=>Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(width:MediaQuery.sizeOf(context).width*.32,margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surface,borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:Theme.of(context).textTheme.labelSmall),const SizedBox(height:5),Text(text)])));
}
